-- Cupo: el plan gratis ya no manda correos a los asistentes (entrada en pantalla y por liga). Cupo Pro agrega los correos
-- (entrada, recordatorios 24 h y 2 h, avisos) además de cover, aprobación, preguntas y equipo. Decisión de Dirección, 19-10-2026.
-- Cupo Pro $139 por evento y paquete de 5 eventos $549 (sale en $109.80 por evento). Se cambian después desde Tienda › Productos.
UPDATE products SET precio_centavos = 13900,
  descripcion_corta = 'Correos automáticos a tus asistentes (entrada, recordatorios y avisos), cobro de cover sin comisión, aprobación de registros y hasta 1,000 personas.',
  contenido = json_set(contenido,
    '$.titular', 'Tu evento con correos, recordatorios y cover',
    '$.subtitulo', 'Arma tu evento gratis en os.vorka.mx/cupo y activa Pro cuando lo vayas a publicar: entrada por correo, recordatorios automáticos, avisos, cover pagado directo a ti y check-in con tu equipo.',
    '$.incluye', json('[{"titulo":"Correos automáticos","texto":"A cada persona le llega su entrada con QR, un recordatorio un día antes y otro dos horas antes."},{"titulo":"10 avisos a tus asistentes","texto":"Cambios de horario, qué traer o cómo llegar, directo a su correo."},{"titulo":"Cobro de cover","texto":"Tu CLABE con botón de copiar, tu liga de pago o pago en la puerta. El dinero llega directo a ti."},{"titulo":"Confirmas pagos con un toque","texto":"La persona avisa que pagó y tú tocas “Pagado”: le llega su entrada con QR."},{"titulo":"Hasta 1,000 personas","texto":"Aprobar registros, preguntas personalizadas y lista de espera automática."},{"titulo":"Check-in con tu equipo","texto":"Una liga para que escaneen desde su celular, sin cuenta, y lista en Excel."}]'),
    '$.faq', json('[{"p":"¿Cupo o Brindi?","r":"Cupo es para eventos rápidos o informales: fiestas, Halloween, networking, talleres y eventos de negocio. Para una boda, XV años o bautizo, donde la invitación es parte del recuerdo, te conviene <a href=\"/tienda/brindi/\">Brindi</a>."},{"p":"¿Qué incluye el plan gratis?","r":"Página del evento, registro y entrada con QR que la persona guarda en su celular, lista de espera y check-in, hasta 100 personas. No manda correos: para entrada por correo, recordatorios y avisos necesitas Pro."},{"p":"¿Puedo armar mi evento antes de pagar?","r":"Sí. En <a href=\"https://os.vorka.mx/cupo/\">os.vorka.mx/cupo</a> lo armas y ves cómo queda sin pagar. Activas Pro solo cuando lo vas a publicar."},{"p":"¿Cupo cobra comisión por mi cover?","r":"No. Las personas te pagan directo a ti y tú confirmas cada pago. Solo pagas Cupo Pro una vez por evento."},{"p":"¿Cómo lo uso después de pagar?","r":"Te llega un correo con el botón “Entrar a Cupo”. Al publicar tu evento eliges usar tu evento Pro."}]')),
  updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 'prod_cupo_pro';
UPDATE products SET precio_centavos = 54900,
  contenido = json_set(contenido, '$.incluye[0].texto', 'Correos y recordatorios, cover, aprobación, preguntas, avisos, check-in con equipo y Excel en cada uno.'),
  updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 'prod_cupo_paquete5';
